def count_pass(scores):
    count = 0
    for score in scores:
        if score >= 60:
            count += 1
    return count

def max_or_none(nums):
    if not nums:
        return None
    best = nums[0]
    for x in nums[1:]:
        if x > best:
            best = x
    return best

def first_index(nums, target):
    for i, x in enumerate(nums):
        if x == target:
            return i
    return -1

