def product(nums):
    result = 1
    for x in nums:
        result *= x
    return result

def running_max(nums):
    result = []
    for x in nums:
        result.append(x if not result else max(x, result[-1]))
    return result

def rotate_right(nums, k):
    if not nums:
        return []
    k %= len(nums)
    return nums[-k:] + nums[:-k] if k else nums[:]

def merge_sorted(a, b):
    i = j = 0
    result = []
    while i < len(a) and j < len(b):
        if a[i] <= b[j]:
            result.append(a[i]); i += 1
        else:
            result.append(b[j]); j += 1
    return result + a[i:] + b[j:]

def second_distinct(nums):
    values = sorted(set(nums))
    return values[-2] if len(values) >= 2 else None

def frequencies(nums):
    result = {}
    for x in nums:
        result[x] = result.get(x, 0) + 1
    return result

def first_unique(nums):
    counts = {}
    for x in nums:
        counts[x] = counts.get(x, 0) + 1
    return next((x for x in nums if counts[x] == 1), None)

def mode_smallest(nums):
    if not nums:
        return None
    counts = {}
    for x in nums:
        counts[x] = counts.get(x, 0) + 1
    return min(counts, key=lambda x: (-counts[x], x))

def binary_search(nums, target):
    left, right = 0, len(nums)-1
    while left <= right:
        mid = (left+right)//2
        if nums[mid] == target:
            return mid
        if nums[mid] < target:
            left = mid+1
        else:
            right = mid-1
    return -1

def lower_bound(nums, target):
    left, right = 0, len(nums)
    while left < right:
        mid = (left+right)//2
        if nums[mid] < target:
            left = mid+1
        else:
            right = mid
    return left

def bubble_sort(nums):
    a = nums[:]
    for end in range(len(a)-1, 0, -1):
        for i in range(end):
            if a[i] > a[i+1]:
                a[i], a[i+1] = a[i+1], a[i]
    return a

def insertion_sort(nums):
    a = nums[:]
    for i in range(1, len(a)):
        x = a[i]
        j = i-1
        while j >= 0 and a[j] > x:
            a[j+1] = a[j]; j -= 1
        a[j+1] = x
    return a

def selection_sort(nums):
    a = nums[:]
    for i in range(len(a)):
        pos = i
        for j in range(i+1, len(a)):
            if a[j] < a[pos]:
                pos = j
        a[i], a[pos] = a[pos], a[i]
    return a

def char_frequencies(text):
    result = {}
    for ch in text:
        result[ch] = result.get(ch, 0) + 1
    return result

def compress_runs(text):
    result = []
    for ch in text:
        if result and result[-1][0] == ch:
            result[-1][1] += 1
        else:
            result.append([ch,1])
    return result

def brackets_ok(text):
    balance = 0
    for ch in text:
        balance += 1 if ch == '(' else -1
        if balance < 0:
            return False
    return balance == 0

def factorial(n):
    result = 1
    for k in range(2,n+1):
        result *= k
    return result

def fibonacci(n):
    a,b = 0,1
    for _ in range(n):
        a,b = b,a+b
    return a

def gcd(a, b):
    while b:
        a,b = b,a%b
    return a

def lcm(a, b):
    if a == 0 or b == 0:
        return 0
    x,y = a,b
    while y:
        x,y = y,x%y
    return a//x*b

def is_prime(n):
    if n < 2:
        return False
    d = 2
    while d*d <= n:
        if n % d == 0:
            return False
        d += 1
    return True

def to_binary(n):
    if n == 0:
        return '0'
    bits = []
    while n:
        bits.append(str(n % 2)); n //= 2
    return ''.join(reversed(bits))

def from_binary(text):
    result = 0
    for ch in text:
        result = result*2 + (1 if ch == '1' else 0)
    return result

def popcount(n):
    count = 0
    while n:
        n &= n-1
        count += 1
    return count

def two_sum_exists(nums, target):
    seen = set()
    for x in nums:
        if target-x in seen:
            return True
        seen.add(x)
    return False

def max_subarray_sum(nums):
    if not nums:
        return None
    current = best = nums[0]
    for x in nums[1:]:
        current = max(x,current+x)
        best = max(best,current)
    return best

def longest_positive_run(nums):
    best = current = 0
    for x in nums:
        current = current+1 if x > 0 else 0
        best = max(best,current)
    return best

def missing_number(nums):
    n = len(nums)
    return n*(n+1)//2-sum(nums)

def majority(nums):
    if not nums:
        return None
    candidate = None
    count = 0
    for x in nums:
        if count == 0:
            candidate = x
        count += 1 if x == candidate else -1
    return candidate if nums.count(candidate) > len(nums)//2 else None

def dedup_adjacent(nums):
    result = []
    for x in nums:
        if not result or result[-1] != x:
            result.append(x)
    return result

def merge_intervals(intervals):
    result = []
    for left,right in sorted(intervals):
        if result and left <= result[-1][1]:
            result[-1][1] = max(result[-1][1],right)
        else:
            result.append([left,right])
    return result

def balanced_all(text):
    stack = []
    pairs = {')':'(',']':'[','}':'{'}
    for ch in text:
        if ch in '([{':
            stack.append(ch)
        elif not stack or stack.pop() != pairs[ch]:
            return False
    return not stack

def reachable(graph, start, target):
    seen = {start}
    stack = [start]
    while stack:
        node = stack.pop()
        if node == target:
            return True
        for nxt in graph.get(node,[]):
            if nxt not in seen:
                seen.add(nxt); stack.append(nxt)
    return False

def shortest_edges(graph, start, target):
    from collections import deque
    queue = deque([(start,0)])
    seen = {start}
    while queue:
        node,d = queue.popleft()
        if node == target:
            return d
        for nxt in graph.get(node,[]):
            if nxt not in seen:
                seen.add(nxt); queue.append((nxt,d+1))
    return -1

def stairs(n):
    a,b = 1,1
    for _ in range(n):
        a,b = b,a+b
    return a

def min_coins(coins, amount):
    dp = [0] + [amount+1]*amount
    for total in range(1,amount+1):
        for coin in coins:
            if coin <= total:
                dp[total] = min(dp[total],dp[total-coin]+1)
    return dp[amount] if dp[amount] <= amount else -1

def lis_length(nums):
    if not nums:
        return 0
    dp = [1]*len(nums)
    for i in range(len(nums)):
        for j in range(i):
            if nums[j] < nums[i]:
                dp[i] = max(dp[i],dp[j]+1)
    return max(dp)
